/**
 * Sirion (SirionOne) B2B API constants.
 *
 * SirionOne is an AI-native Contract Lifecycle Management platform. Its B2B
 * API is a tenant-scoped REST API: every customer is provisioned on their own
 * SirionOne host (e.g. https://<tenant>.sirion.ai), and OAuth Client
 * credentials (Client ID + Client Secret, generated by a client admin under
 * Admin 2.0 → OAuth Client Setup) are exchanged for a Bearer access token via
 * the tenant's `/oauth/token` endpoint using the OAuth 2.0 client-credentials
 * grant. SirionOne exposes contracts as the top-level agreement object, with
 * nested signatories, attached documents, an activity/audit history, and
 * reusable contract templates.
 *
 * Because the host is per-tenant, the real base URL is resolved at runtime
 * from `credentials.extra.baseUrl`. The constants below pin the API path
 * prefix, the OAuth token path, and sensible defaults.
 *
 * Refs: Sirion self-serve B2B API + OAuth Client Setup (Admin 2.0); SirionOne
 * product documentation.
 */

/** API path prefix appended to the tenant host. */
export const API_PATH_PREFIX = '/b2b/v1'

/** OAuth 2.0 token endpoint path (client-credentials grant), tenant-scoped. */
export const OAUTH_TOKEN_PATH = '/oauth/token'

/**
 * Default tenant host. SirionOne is multi-tenant; the real host is supplied
 * per-connection via `credentials.extra.baseUrl`. This default keeps the
 * adapter constructible without a tenant and documents the canonical shape.
 */
export const DEFAULT_BASE_URL = 'https://app.sirion.ai'

export const DEFAULT_PAGE_SIZE = 50
export const MAX_PAGE_SIZE = 200

/**
 * Default scopes. Sirion's B2B API token permissions are configured on the
 * OAuth Client (Admin 2.0); `read` covers the read-only resources this
 * adapter exposes.
 */
export const DEFAULT_SCOPES = ['read']
